(function(root){'use strict';
function create(h){const {t,loc,icon,btn,data,cr,num,duration,action,open,close,watchAd,toast}=h;let last='';const colors=['#a6ff78','#60f2ec','#ffa45f','#b99aff','#fb91cc','#ffe191'],claimAccent='#61f2e7';
const titles={ready:['Carrier ready','Carrier готов'],travel:['Carrier in transit','Carrier в пути'],deploying:['Node Station online','Node Station активна'],active:['Swarm mining','Рой майнит'],broken:['Swarm needs repair','Рою нужен ремонт']};
function claimSlot(s){const j=s.state.homeJourney,x=s.home,cooling=s.now<s.ads.nextAt;
 const timer=`${t('Next ad in ','Реклама через ')}<span data-home-live="ad">${duration(s.ads.nextAt-s.now)}</span>`;
 if(j.completedAt&&!j.firstRewardDoubled)return {action:'homeDouble',disabled:cooling,content:`<span>${t('First reward collected!','Первая награда получена!')}</span><strong>${cooling?timer:t('Ad → +','Реклама → +')+cr(j.firstReward)+' CR'}</strong>`};
 if(cooling)return {action:'',disabled:true,content:`<span>${t('Rewarded ad','Реклама за награду')}</span><strong>${timer}</strong>`};
 if(x.bonusUntil>s.now)return {action:'homeCollect',disabled:false,content:`<span>${t('Welcome boost ×2','Стартовый буст ×2')}</span><strong data-home-live="welcome">${duration(x.bonusUntil-s.now)}</strong>`};
 return {action:'homeCollect',disabled:false,content:`<span>${t('Automatic DATA collection','Автоматическая добыча DATA')}</span><strong>${t('Your swarm is online','Ваш рой в сети')}</strong>`};
}
function claimCard(s){const x=s.home,slot=claimSlot(s);return `<div class="claim-card" style="--claim-accent:${claimAccent}"><button class="claim-button" data-action="homeCollect" ${x.claimCents<1?'disabled':''}><span class="claim-content"><span class="claim-label">${t('Collect DATA','Собрать DATA')}</span><strong class="data-value"><span data-home-live="data">${data(x.amount)}</span> <small>DATA</small></strong><span class="claim-bottom">≈ <span data-home-live="equivalent">${cr(x.claimCents)}</span> CR</span></span></button><button class="claim-slot" ${slot.action?`data-action="${slot.action}"`:''} ${slot.disabled?'disabled':''} aria-label="${t('Swarm status','Статус роя')}">${slot.content}</button></div>`;}
function signature(s){const x=s.home,e=x.expedition;return JSON.stringify([x.galaxy.id,x.phase,x.releasing,x.minimal,x.partial,x.tier.tier,x.dots,x.first,!!s.state.homeJourney.completedAt,s.state.homeJourney.firstRewardDoubled,s.now<s.ads.nextAt,e?.welcomeBoostUntil>s.now,e?.boost4Until>s.now,e?.overclockUntil>s.now]);}
function render(s){last=signature(s);const x=s.home,e=x.expedition,j=s.state.homeJourney,active=x.phase==='active',station=x.phase==='deploying',asset=station?'assets/home-station.png':active||x.phase==='broken'?'assets/depin-probe.png':'assets/home-carrier.png',shortcut=(i,a,en,ru)=>btn(icon(i)+`<span>${t(en,ru)}</span>`,a,'','mini-card orbit-shortcut');
 const side=x.minimal?'':`<div class="orbit-rail rail-left">${!x.partial?shortcut('friends','socHub','Soc Hub','Соц хаб'):''}</div><div class="orbit-rail rail-right">${!x.partial?shortcut('combo','comboMenu','Combo','Комбо'):''}</div>`;
 const lore=x.phase==='ready'?t('Year 2800. Your Carrier is ready for the first frontier.','2800 год. Ваш Carrier готов к освоению новых миров.'):x.phase==='travel'?t('Approaching sector ','Прибытие в сектор ')+x.galaxy.sector+'…':station?(x.releasing?t('Airlocks open. Deploying the probe swarm…','Шлюзы открыты. Выпускаем рой зондов…'):t('Station activated. Initializing the swarm…','Станция активирована. Инициализация роя…')):x.first?t('Swarm deployed. Collect your first DATA.','Рой развёрнут. Соберите первые DATA.'):t('Autonomous collection · '+loc(x.tier.name),'Автономный сбор · '+loc(x.tier.name));
 const timer=e?(x.phase==='travel'?e.arrivesAt-s.now:station?e.activeAt-s.now:0):0,progress=e?(x.phase==='travel'?(s.now-e.startedAt)/(e.arrivesAt-e.startedAt):station?(s.now-e.arrivesAt)/(e.activeAt-e.arrivesAt):1):0;
 return `<div class="journey-selector"><button data-action="homeGalaxies">${icon('globe')}<span>${loc(x.galaxy.name)} <small>${x.galaxy.sector}</small></span><b>⌄</b></button><span class="journey-phase">${loc(titles[x.phase])}</span></div><section class="hero compact-hero journey-hero phase-${x.phase} ${x.releasing?'swarm-releasing':''}" style="--swarm-color:${colors[x.tier.tier-1]};--tier-hue:${[290,0,190,70,110,230][x.tier.tier-1]}deg" aria-label="${loc(titles[x.phase])}">${x.phase==='travel'?`<div class="hyperspace" aria-hidden="true">${Array.from({length:9},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div>`:''}${active||x.releasing?`<div class="swarm-orbit ${x.releasing?'swarm-emerging':''}" aria-hidden="true">${Array.from({length:x.dots},(_,i)=>`<span class="swarm-dot" style="--angle:${i*360/x.dots}deg;--delay:${-i*3}s"></span>`).join('')}</div>`:''}<img class="hero-art sonde-art journey-device ${station?'station-device':active||x.phase==='broken'?'probe-device':'carrier-device'} tier-${x.tier.tier}" src="${asset}" alt="${station?'Node Station':active?loc(x.tier.name):'Carrier'}">${side}<div class="journey-caption"><p>${lore}</p>${timer>0?`<div class="journey-progress"><span data-home-progress style="width:${Math.min(100,Math.max(0,progress*100))}%"></span></div><strong data-home-live="timer">${duration(timer)}</strong>`:active?`<span>TIER ${x.tier.tier} · <b>${num(Math.floor(x.metrics.rate/s.state.settings.microPerHashHour))} H/s</b> · <span data-home-live="rate">${data(x.metrics.rate)}</span> DATA/${t('h','ч')}</span>`:''}</div></section><div class="mining-zone journey-actions">${x.phase==='ready'?`${btn(t('Launch now · Free','Запустить сейчас · Бесплатно'),'homeLaunch','','primary full')}${btn(icon('play')+t('Watch ad · No flight wait','Реклама · Без ожидания перелёта'),'homeLaunchAd',s.now<s.ads.nextAt?'disabled':'','secondary full')}`:active?claimCard(s):x.phase==='broken'?btn(t('Open repair controls','Открыть ремонт'),'homeManage','','secondary full'):btn(icon('play')+(station?t('Release swarm now · Ad','Выпустить рой сейчас · Реклама'):e.travelReduced?t('Flight already accelerated','Перелёт уже ускорен'):t('Flight time −50% · Ad','Перелёт −50% · Реклама')),'homeAccelerate',s.now<s.ads.nextAt||(!station&&e.travelReduced)?'disabled':'','secondary full')}${!active&&s.now<s.ads.nextAt?`<small class="journey-ad-time">${t('Next ad in ','Реклама через ')}<span data-home-live="ad">${duration(s.ads.nextAt-s.now)}</span></small>`:''}</div>${x.minimal?`<div class="journey-training">${btn(icon('bolt')+t('Mining boost','Буст майнинга'),'homeBoost',active?'':'disabled','secondary')}<small>${t('Carrier → Node Station → Swarm','Carrier → Node Station → Рой')}</small></div>`:activities(s)}${j.first&&x.partial?`<p class="journey-unlocks">${t('All shortcuts unlock when your swarm starts mining.','Все быстрые действия откроются, когда рой начнёт добычу.')}</p>`:''}`;
}
function activities(s){const tiles=[['gift','daily','Daily<br>bonus','Ежедневный<br>бонус',s.dailyReady?t('Claim','Забрать'):duration(s.state.lastDaily+s.state.settings.daily.intervalMs-s.now)],['bolt','homeBoost','Mining<br>boost','Буст<br>майнинга','×2 / ×4'],['gem','giftMenu','Gifts','Подарки','+100 Gems'],['tasks','missions','Seasonal<br>missions','Сезонные<br>миссии',Math.max(0,Math.floor((s.seasonEnd-s.now)/86400000))+t('d','д')],['shop','shopMenu','Seasonal<br>shop','Сезонный<br>магазин',t('Exclusive','Эксклюзив')]].filter(tile=>tile[1]!=='giftMenu'||!s.state.giftClaimed);return `<div class="home-cards compact-activities">${tiles.map(([i,a,en,ru,value])=>`<button class="mini-card activity-tile" data-action="${a}"><h3>${t(en,ru)}</h3><span class="activity-icon">${icon(i)}</span><strong class="activity-value">${value}</strong></button>`).join('')}</div>`;}
async function click(a){const s=h.view(),x=s.home,g=x.galaxy.id;switch(a){case'homeGalaxies':open(t('Active galaxy','Активная галактика'),s.state.nodeHub.settings.galaxies.map(g=>btn(loc(g.name)+' · '+g.sector,'homeSelect',`data-galaxy="${g.id}" ${g.hazard&&!s.state.nodes.orbital?'disabled':''}`,'secondary full')).join(''));break;case'homeLaunch':await action('homeLaunch',{galaxy:g});break;case'homeLaunchAd':await watchAd({purpose:'launch',galaxy:g});break;case'homeAccelerate':await watchAd({purpose:x.phase==='travel'?'travel':'deploy',galaxy:g});break;case'homeCollect':{const out=await action('homeCollect',{galaxy:g});if(out){if(typeof MotionUI!=='undefined')MotionUI.claim(out.collected,s.state.settings.microPerData);toast('+'+cr(out.credited)+' CR'+(out.welcome?' · '+t('Welcome boost ×2 for 30 min','Стартовый буст ×2 на 30 мин'):''));}break;}case'homeDouble':await watchAd({purpose:'firstReward'});break;case'homeManage':h.route('nodes');break;case'homeBoost':open(t('Boost this galaxy','Буст текущей галактики'),`<p class="subtitle">${loc(x.galaxy.name)} · ${t('Boosts do not stack. The strongest active multiplier applies.','Бусты не перемножаются. Действует самый сильный.')}</p>${btn('×2 · 24 '+t('hours · Ad','часа · Реклама'),'homeAd2',s.now<s.ads.nextAt||x.phase!=='active'||s.now<x.expedition.overclockUntil?'disabled':'','primary full')}${btn('×4 · 15 '+t('min · Ad','мин · Реклама'),'homeAd4',s.now<s.ads.nextAt||x.phase!=='active'||s.now<(x.expedition.boost4Until||0)?'disabled':'','secondary full')}`);break;case'homeAd2':await close();await watchAd({purpose:'overclock',galaxy:g});break;case'homeAd4':await close();await watchAd({purpose:'boost4',galaxy:g});break;}}
function tick(s){if(signature(s)!==last){h.render();return;}const x=s.home,e=x.expedition,set=(key,value)=>document.querySelectorAll(`[data-home-live="${key}"]`).forEach(el=>el.textContent=value);if(typeof MotionUI!=='undefined'){document.querySelectorAll('[data-home-live="data"]').forEach(el=>MotionUI.number(el,x.amount,n=>data(Math.floor(n/100)*100)));document.querySelectorAll('[data-home-live="equivalent"]').forEach(el=>MotionUI.number(el,x.claimCents,n=>cr(Math.floor(n)),{duration:145}));}else{set('data',data(x.amount));set('equivalent',cr(x.claimCents));}set('rate',data(x.metrics.rate));set('ad',duration(s.ads.nextAt-s.now));set('welcome',duration(x.bonusUntil-s.now));if(e){const travel=x.phase==='travel',timer=travel?e.arrivesAt:e.activeAt,start=travel?e.startedAt:e.arrivesAt;set('timer',duration(timer-s.now));document.querySelectorAll('[data-home-progress]').forEach(el=>el.style.width=Math.max(0,Math.min(100,(s.now-start)/(timer-start)*100))+'%');}document.querySelectorAll('[data-action="homeCollect"]').forEach(el=>el.disabled=h.busy()||x.claimCents<1);}
return {render,click,tick};}
root.HomeUI={create};if(typeof module==='object')module.exports={create};
})(typeof globalThis!=='undefined'?globalThis:window);
